/* Define Type Tags matching specification */
typedef enum {
  TAG_NULL          = 0,
  TAG_INT32         = 1,
  TAG_DOUBLE        = 2,
  TAG_STRING        = 3,
  TAG_SHORT_STRING  = 4,
  TAG_MEDIUM_STRING = 5,
  TAG_COMPLEX       = 6,
  TAG_BOOL          = 7,
  TAG_UINT8         = 8,
  TAG_UINT16        = 9,
  TAG_UINT32        = 10,
  TAG_LONGDOUBLE    = 11,
  TAG_INT64         = 12,
  TAG_DD            = 13
} DataTypeTag;

/*
===============================================================================
  PACKING IMPLEMENTATION (Uses a standard dynamic byte buffer)
===============================================================================
*/
typedef struct {
  uint8_t *data;
  size_t size;
  size_t cap;
} Buffer;

/* static Buffer *binpack_newbuffer (void) {
  Buffer *b = (Buffer *)malloc(sizeof(Buffer));
  binpack_init(b);
  return b;
} */

static void binpack_init (Buffer *b) {
  if (b == NULL) return;
  b->data = NULL;
  b->size = 0;
  b->cap  = 0;
}

static void buf_ensure (Buffer *b, size_t len) {
  if (b->size + len > b->cap) {
    while (b->size + len > b->cap) b->cap = b->cap ? b->cap * 2 : 64;
    b->data = (uint8_t*)realloc(b->data, b->cap);
  }
}

/* --- PACKING FUNCTIONS --- */

static void pack_int32 (Buffer *buf, int32_t val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(int32_t);
  #if BYTE_ORDER == BIG_ENDIAN
  val = tools_swapi32(val);
  #endif
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_INT32;
  memcpy(buf->data + buf->size, &val, sizeof(int32_t));
  buf->size += sizeof(int32_t);
}

static void pack_int64 (Buffer *buf, int64_t val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(int64_t);
  #if BYTE_ORDER == BIG_ENDIAN
  val = tools_swapi64(val);
  #endif
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_INT64;
  memcpy(buf->data + buf->size, &val, sizeof(int64_t));
  buf->size += sizeof(int64_t);
}

static void pack_double (Buffer *buf, double val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(double);
  #if BYTE_ORDER == BIG_ENDIAN
  val = tools_tolittleendian(val);
  #endif
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_DOUBLE;
  memcpy(buf->data + buf->size, &val, sizeof(double));
  buf->size += sizeof(double);
}

#ifndef PROPCMPLX
static void pack_complex (Buffer *buf, agn_Complex val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(agn_Complex);
  #if BYTE_ORDER == BIG_ENDIAN
  __real__ val = tools_tolittleendian(creal(val));
  __imag__ val = tools_tolittleendian(cimag(val));
  #endif
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_COMPLEX;
  memcpy(buf->data + buf->size, &val, sizeof(agn_Complex));
  buf->size += sizeof(agn_Complex);
}
#else
static void pack_complex (Buffer *buf, lua_Number val[2]) {
  size_t total_needed = sizeof(uint8_t) + 2*sizeof(lua_Number);
  #if BYTE_ORDER == BIG_ENDIAN
  __real__ val[0] = tools_tolittleendian(val[0]);
  __imag__ val[1] = tools_tolittleendian(val[1]);
  #endif
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_COMPLEX;
  memcpy(buf->data + buf->size, val, 2*sizeof(lua_Number));
  buf->size += 2*sizeof(lua_Number);
}
#endif


static void pack_dd (Buffer *buf, dd_pair val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(dd_pair);
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_DD;
  memcpy(buf->data + buf->size, &val, sizeof(dd_pair));
  buf->size += sizeof(dd_pair);
}

#ifndef __ARMCPU
static void pack_longdouble (Buffer *buf, long double val) {
  /* Force exactly 10 bytes of allocation space (1-byte tag + 10-byte payload) */
  size_t total_needed = sizeof(uint8_t) + 10;
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_LONGDOUBLE;
  /* Copy ONLY the 10 real data bytes, ignoring any trailing compiler padding */
  memcpy(buf->data + buf->size, &val, 10);
  buf->size += 10;
}
#endif

/* char val: 0 = false, 1 = true, -1 = fail */
static void pack_bool (Buffer *buf, char val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(uint8_t);  /* tag + 1-byte value */
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_BOOL;
  buf->data[buf->size++] = (val == -1 || val == 255) ? 2 : val;  /* 255 is for ARM since char is UNSIGNED there [sic !] */
}

static void pack_null (Buffer *buf) {
  size_t total_needed = sizeof(uint8_t);  /* tag only */
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_NULL;
}

static void pack_uchar (Buffer *buf, unsigned char val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(uint8_t);  /* tag + 1-byte value */
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_UINT8;
  buf->data[buf->size++] = val;
}

static void pack_uint16 (Buffer *buf, uint16_t val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(uint16_t);  /* tag + 1-byte value */
  #if BYTE_ORDER == BIG_ENDIAN
  val = tools_swapuint16(val);
  #endif
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_UINT16;
  memcpy(buf->data + buf->size, &val, sizeof(uint16_t));
  buf->size += sizeof(uint16_t);
}

static void pack_uint32 (Buffer *buf, uint32_t val) {
  size_t total_needed = sizeof(uint8_t) + sizeof(uint32_t);  /* tag + 1-byte value */
  #if BYTE_ORDER == BIG_ENDIAN
  val = tools_swapuint32(val);
  #endif
  buf_ensure(buf, total_needed);
  buf->data[buf->size++] = TAG_UINT32;
  memcpy(buf->data + buf->size, &val, sizeof(uint32_t));
  buf->size += sizeof(uint32_t);
}

static void pack_string (Buffer *buf, const char *str, size_t len) {
  if (len < 256) {
    uint8_t short_len = (uint8_t)len;
    size_t total_needed = sizeof(uint8_t) + sizeof(uint8_t) + short_len;
    buf_ensure(buf, total_needed);
    buf->data[buf->size++] = TAG_SHORT_STRING;
    buf->data[buf->size++] = short_len;
    memcpy(buf->data + buf->size, str, short_len);
    buf->size += short_len;
  } else if (len < 65536) {
    uint16_t medium_len = (uint16_t)len;
    size_t total_needed = sizeof(uint8_t) + sizeof(uint16_t) + medium_len;
    buf_ensure(buf, total_needed);
    buf->data[buf->size++] = TAG_MEDIUM_STRING;
    #if BYTE_ORDER == BIG_ENDIAN
    medium_len = tools_swapuint16(medium_len);
    #endif
    memcpy(buf->data + buf->size, &medium_len, sizeof(uint16_t));
    buf->size += sizeof(uint16_t);
    memcpy(buf->data + buf->size, str, (uint16_t)len);
    buf->size += medium_len;
  } else {
    uint32_t long_len = (uint32_t)len;
    size_t total_needed = sizeof(uint8_t) + sizeof(uint32_t) + long_len;
    buf_ensure(buf, total_needed);
    buf->data[buf->size++] = TAG_STRING;
    #if BYTE_ORDER == BIG_ENDIAN
    long_len = tools_swapuint32(long_len);
    #endif
    memcpy(buf->data + buf->size, &long_len, sizeof(uint32_t));
    buf->size += sizeof(uint32_t);
    memcpy(buf->data + buf->size, str, (uint32_t)len);
    buf->size += long_len;
  }
}


