static int binpack_uchar (lua_State* L) {
  int i, nargs = lua_gettop(L);
  Buffer *b = (Buffer *)luaL_checkudata(L, 1, AGENA_BINPACKLIBNAME);
  for (i=2; i <= nargs; i++) {
    uint8_t val = (uint8_t)(luaL_checkinteger(L, i) & 0xFF);
    pack_uchar(b, val);
  }
  lua_settop(L, 1);
  return 1;  /* Return self for chaining */
}


